def spread_chars(s):
    from collections import Counter
    if not s:
        return ''
    counts = Counter(s)
    heap = [(-c, ch) for ch, c in counts.items()]
    import heapq
    heapq.heapify(heap)
    out = []
    while heap:
        c, ch = heapq.heappop(heap)
        out.append(ch)
        c += 1
        if c:
            heapq.heappush(heap, (c, ch))
    if len(out) != len(s):
        return ''
    for i in range(1, len(out)):
        if out[i] == out[i - 1]:
            return ''
    return ''.join(out)
```

